function coachPlan(){return COACH_PLANS[state.coachPlan]||COACH_PLANS["30"]}
function coachDay(){const p=coachPlan();return Math.max(1,Math.min(p.days,Number(state.coachPlanDays[state.coachPlan]||1)))}
function setCoachPlan(id){if(!COACH_PLANS[id])return;state.coachPlan=id;if(!state.coachPlanDays[id])state.coachPlanDays[id]=1;coachSession=null;save();renderCoach();renderDashboard();pushAppHistory("coach",{coachSession:false})}
function termUse(t){const map={"Фандрайзинг":"Раунды, переговоры с инвесторами и условия сделки.","Финансы":"Финансовая модель, бюджет и экономика бизнеса.","Метрики":"Отчёты, рост продукта и вопросы инвестора о цифрах.","Рынок":"Оценка рынка, клиентов и конкурентов.","Рост":"Продажи, маркетинг и масштабирование.","Бизнес":"Бизнес-модель, продукт и монетизация.","Коммуникация":"Pitch, встречи и ответы инвестору.","Право":"Документы, права инвесторов и структура компании."};return map[t?.cat]||"В разговоре с инвестором и управлении стартапом."}
function coachGuide(t){const g=COACH_GUIDES[t.id]||{},goals={"Метрики":"Понять качество роста через цифры, а не впечатления.","Финансы":"Понять устойчивость экономики и потребность в капитале.","Рынок":"Понять кому нужен продукт и насколько велик рынок.","Рост":"Понять, можно ли повторяемо привлекать клиентов.","Фандрайзинг":"Понять экономику раунда, ownership и риски условий.","Право":"Понять контроль, права сторон и юридические риски.","Бизнес":"Понять как продукт создаёт ценность и выручку.","Коммуникация":"Понять, может ли основатель ясно объяснить бизнес."};let benchmark=g.benchmark;if(!benchmark)benchmark=(t.cat==="Метрики"||t.cat==="Финансы")?"Универсального проходного числа нет. Важно точное определение, период, динамика, сегмент и связь с соседними метриками.":"Универсального числового порога нет. Сильный ответ конкретный и подтверждён данными, примером или документом.";return {purpose:t.why||`Термин нужен, чтобы точно говорить о ${termUse(t).toLowerCase()}`,investorGoal:g.investorGoal||goals[t.cat]||"Понять конкретный риск или качество бизнеса.",benchmark,best:g.best||"Ответьте одним тезисом и подтвердите его цифрой, примером или документом.",use:termUse(t)}}
function coachStat(id){if(!state.coachStats[id])state.coachStats[id]={seen:0,right:0,wrong:0,streak:0,last:""};return state.coachStats[id]}
function coachAccuracy(id){const s=coachStat(id),n=(s.right||0)+(s.wrong||0);return n?s.right/n:0}
function coachLevel(id){const s=coachStat(id),a=coachAccuracy(id);if(s.seen<2||a<.55)return 1;if(s.seen<5||a<.82)return 2;return 3}
function coachLevelName(id){return ["","Разбираем с нуля","Закрепляем на примерах","Тренируем как на встрече"][coachLevel(id)]}
function coachPriority(t){const s=coachStat(t.id),a=coachAccuracy(t.id),weak=state.weak.includes(t.id)?8:0,due=(state.srs[t.id]&&state.srs[t.id].due<=today())?6:0,unseen=s.seen===0?10:0;return unseen+weak+due+(s.wrong||0)*2+(s.seen?Math.round((1-a)*8):0)-Math.min(5,s.right||0)}
function coachFocusTerms(){const p=coachPlan(),d=coachDay();if(state.coachPlan==="7")return (COACH_WEEK[(d-1)%7]||[]).map(term).filter(Boolean);const start=((d-1)*p.newPerDay)%TERMS.length,out=[];for(let i=0;i<Math.min(p.newPerDay,TERMS.length);i++)out.push(TERMS[(start+i)%TERMS.length]);return out}
function coachPool(){const priority=[...dueTerms(),...state.weak.map(term).filter(Boolean),...coachFocusTerms()].filter(Boolean),seen=new Set(),out=[];for(const t of priority.sort((a,b)=>coachPriority(b)-coachPriority(a)))if(!seen.has(t.id)){seen.add(t.id);out.push(t)}for(const t of TERMS.slice().sort((a,b)=>coachPriority(b)-coachPriority(a)))if(!seen.has(t.id)){seen.add(t.id);out.push(t)}return out}
function coachDecoys(correct,count=2){const same=TERMS.filter(t=>t.id!==correct.id&&t.cat===correct.cat),pool=[...same,...TERMS.filter(t=>t.id!==correct.id&&!same.some(x=>x.id===t.id))],out=[];for(const t of pool){if(out.length>=count)break;if(!out.some(x=>x.id===t.id))out.push(t)}return out}
function coachShuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function coachChoices(t,field){const options=coachShuffle([t,...coachDecoys(t,2)]);return {options:options.map(x=>field(x)),answer:options.findIndex(x=>x.id===t.id)}}
function coachRecoveryTask(t){const dec=coachDecoys(t,2),opts=coachShuffle([t.simple,dec[0]?.simple||"Другое понятие",dec[1]?.simple||"Другое понятие"]);return {type:"recovery",termId:t.id,prompt:`Сначала проще. Что означает «${t.word}»?`,options:opts,answer:opts.indexOf(t.simple),answered:false,selected:-1}}
function buildCoachTasks(t){const g=coachGuide(t),level=coachLevel(t.id),scenario=coachChoices(t,x=>x.word),purpose=coachChoices(t,x=>coachGuide(x).investorGoal),dec=coachDecoys(t,2),bench=coachShuffle([g.benchmark,coachGuide(dec[0]).benchmark,coachGuide(dec[1]).benchmark]),responses=coachShuffle([g.best,coachGuide(dec[0]).best,coachGuide(dec[1]).best]),tasks=[{type:"lesson",termId:t.id},{type:"scenario",termId:t.id,prompt:`Ситуация: ${t.example||t.simple} Какой термин здесь нужен?`,options:scenario.options,answer:scenario.answer,answered:false,selected:-1},{type:"investor",termId:t.id,prompt:`Инвестор спрашивает: «${t.investor||`Что показывает ${t.word}?`}» Что он на самом деле проверяет?`,options:purpose.options,answer:purpose.answer,answered:false,selected:-1}];if(level>=2)tasks.push({type:"benchmark",termId:t.id,prompt:`Как правильнее оценивать «${t.word}» на реальной встрече?`,options:bench,answer:bench.indexOf(g.benchmark),answered:false,selected:-1});tasks.push({type:"response",termId:t.id,prompt:`Какой ответ основателя на вопрос про «${t.word}» звучит сильнее всего?`,options:responses,answer:responses.indexOf(g.best),answered:false,selected:-1});return tasks}
function startCoach(count=2){const chosen=coachPool().slice(0,Math.max(1,Math.min(2,count))),groups=chosen.map(buildCoachTasks),tasks=[],max=Math.max(...groups.map(g=>g.length));for(let step=0;step<max;step++)for(const group of groups)if(group[step])tasks.push(group[step]);coachSession={count:chosen.length,index:0,tasks,terms:chosen.map(t=>t.id),plan:state.coachPlan,day:coachDay(),answered:0,correct:0,mistakes:[]};renderCoach();pushAppHistory("coach",{coachSession:true,coachIndex:0})}
function coachAnswer(i){const task=coachSession?.tasks?.[coachSession.index];if(!task||task.type==="lesson"||task.answered)return;task.selected=i;task.answered=true;const ok=i===task.answer,s=coachStat(task.termId);s.seen=(s.seen||0)+1;s.last=today();coachSession.answered=(coachSession.answered||0)+1;if(ok){s.right=(s.right||0)+1;s.streak=(s.streak||0)+1;coachSession.correct=(coachSession.correct||0)+1}else{s.wrong=(s.wrong||0)+1;s.streak=0;if(!coachSession.mistakes.includes(task.termId))coachSession.mistakes.push(task.termId)}updateSRS(task.termId,ok);save();renderCoach();renderDashboard()}
function coachNext(){if(!coachSession)return;const task=coachSession.tasks[coachSession.index];if(task.type!=="lesson"&&!task.answered)return;if(task.type==="lesson"){const s=coachStat(task.termId);s.seen=(s.seen||0)+1;s.last=today();save()}coachSession.index++;renderCoach();pushAppHistory("coach",{coachSession:true,coachIndex:coachSession.index})}
function coachBack(){if(history.state?.view==='coach'&&window.history.length>1){history.back();return}if(coachSession&&coachSession.index>0){coachSession.index--;renderCoach()}else{coachSession=null;renderCoach()}}
function coachNextDay(){const p=coachPlan(),d=coachDay();state.coachPlanDays[state.coachPlan]=d>=p.days?1:d+1;save();coachSession=null;renderCoach();renderDashboard();pushAppHistory("coach",{coachSession:false})}
function coachTaskComment(task,t){const g=coachGuide(t);if(task.type==="scenario")return `Здесь важен контекст: ${t.word} используют, когда нужно ${g.use.toLowerCase()}.`;if(task.type==="investor")return `Инвестор спрашивает не ради термина. Он проверяет: ${g.investorGoal}`;if(task.type==="benchmark")return g.benchmark;if(task.type==="response")return `Сильный ответ не пересказывает определение. Он даёт конкретику: ${g.best}`;return t.simple}
function coachFeedback(task,t){const ok=task.selected===task.answer;return `<div class="answer-result ${ok?'is-correct':'is-wrong'}"><strong>${ok?'Правильно':'Неправильно'}</strong></div>${!ok?`<div class="answer-line wrong-line"><span>Ваш ответ</span><strong>${safe(task.options[task.selected])}</strong></div>`:''}<div class="answer-line correct-line"><span>Правильный ответ</span><strong>${safe(task.options[task.answer])}</strong></div><div class="feedback lesson-feedback"><p><strong>Комментарий:</strong> ${safe(coachTaskComment(task,t))}</p></div>`}
function coachPlanTabs(){return `<div class="filterbar coach-plan-tabs">${Object.entries(COACH_PLANS).map(([id,p])=>`<button class="${state.coachPlan===id?'active':''}" onclick="setCoachPlan('${id}')">${p.label}</button>`).join('')}</div>`}
function coachBackButton(){return `<button class="btn secondary coach-back" onclick="coachBack()">← Назад</button>`}
function renderCoach(){const root=$("#view-coach");if(!root)return;const p=coachPlan(),d=coachDay();if(!coachSession){const focus=coachFocusTerms().slice(0,6).map(t=>t.word).join(" · "),weak=TERMS.filter(t=>state.weak.includes(t.id)).length;root.innerHTML=`<div class="card"><span class="tag">COACH · ГЛАВНЫЙ РЕЖИМ</span><h2>Персональный тренер</h2>${coachPlanTabs()}<p><strong>${safe(p.title)} · день ${d} из ${p.days}</strong></p><p class="muted">${safe(p.desc)} Ритм: ${safe(p.pace)}.</p><p><strong>Фокус:</strong> ${safe(focus||"Coach выберет нужные термины по вашим ответам.")}</p>${weak?`<p class="muted">Coach видит ${weak} слабых тем и поднимет их выше в следующих подходах.</p>`:""}<div class="row"><button class="btn" onclick="startCoach(2)">Начать · 2 термина</button><button class="btn secondary" onclick="startCoach(1)">1 термин</button></div></div>`;return}if(coachSession.index>=coachSession.tasks.length){const score=coachSession.answered?Math.round((coachSession.correct||0)/coachSession.answered*100):100,mistakes=(coachSession.mistakes||[]).map(term).filter(Boolean);root.innerHTML=`<div class="card">${coachBackButton()}<span class="tag">ПОДХОД ЗАВЕРШЁН</span><h2>${score}% за этот подход</h2><p>${score>=82?'Термины поняты в разных контекстах. Можно идти дальше.':score>=60?'Основа есть. Ошибочные понятия вернутся позже, а не сразу тем же объяснением.':'Есть пробелы. Coach поставит эти темы выше в следующих подходах.'}</p>${mistakes.length?`<p><strong>Вернуть позже:</strong> ${mistakes.map(t=>safe(t.word)).join(' · ')}</p>`:''}<div class="row"><button class="btn" onclick="startCoach(${coachSession.count})">Ещё подход</button><button class="btn secondary" onclick="coachNextDay()">Следующий день плана</button></div></div>`;return}const task=coachSession.tasks[coachSession.index],t=term(task.termId),g=coachGuide(t),n=coachSession.index+1,total=coachSession.tasks.length,level=coachLevelName(t.id);if(task.type==="lesson"){root.innerHTML=`<div class="quiz"><div class="row between">${coachBackButton()}<span class="muted small">${safe(level)}</span></div><div class="row between"><span class="tag">COACH · ${n}/${total}</span><span class="muted small">${safe(t.cat)}</span></div><div class="card quiz-card"><h2>${safe(t.word)}</h2><p class="muted">${safe(t.full)}</p><div class="feedback lesson-feedback"><p><strong>Что это:</strong> ${safe(t.simple)}</p><p class="muted small">Полный разбор показывается один раз. Дальше — только практика.</p><p><strong>Зачем нужен:</strong> ${safe(g.purpose)}</p><p><strong>Почему инвестор спрашивает:</strong> ${safe(g.investorGoal)}</p><p><strong>Что считается сильным:</strong> ${safe(g.benchmark)}</p>${t.example?`<p><strong>Пример:</strong> ${safe(t.example)}</p>`:""}${t.formula?`<p><strong>Формула:</strong> ${safe(t.formula)}</p>`:""}<p><strong>Частый вопрос:</strong> ${safe(t.investor||`Что показывает ${t.word}?`)}</p><p><strong>Как отвечать:</strong> ${safe(g.best)}</p><p><strong>Где используется:</strong> ${safe(g.use)}</p></div><button class="btn feedback-next" onclick="coachNext()">Проверить на практике</button></div></div>`;return}const labels={scenario:"Применение",investor:"Логика инвестора",benchmark:"Оценка метрики",response:"Ответ на встрече"};root.innerHTML=`<div class="quiz"><div class="row between">${coachBackButton()}<span class="muted small">${safe(level)}</span></div><div class="row between"><span class="tag">COACH · ${n}/${total}</span><span class="muted small">${labels[task.type]||"Практика"}</span></div><div class="card quiz-card"><h2>${safe(task.prompt)}</h2><div>${task.options.map((o,i)=>`<button class="option ${task.answered?(i===task.answer?'correct':i===task.selected?'wrong':''):''}" ${task.answered?'disabled':''} onclick="coachAnswer(${i})">${safe(o)}</button>`).join("")}</div>${task.answered?`${coachFeedback(task,t)}<button class="btn feedback-next" onclick="coachNext()">Следующий шаг</button>`:""}</div></div>`}

let quizIndex=0,quizAnswered=false,lastAnswer=-1,currentQuiz=null;
function buildQuizQueue(){const dueIds=new Set(dueTerms().map(t=>t.id));const weakIds=new Set(state.weak);return [...QUIZ].sort((a,b)=>(dueIds.has(b.termId)?3:0)+(weakIds.has(b.termId)?2:0)-((dueIds.has(a.termId)?3:0)+(weakIds.has(a.termId)?2:0)))}
function getQuiz(){const q=buildQuizQueue();return q[quizIndex%q.length]}
function quizFeedback(q){const t=term(q.termId);const ok=lastAnswer===q.a;return `<div class="answer-result ${ok?'is-correct':'is-wrong'}"><strong>${ok?'Правильно':'Неправильно'}</strong></div>${!ok?`<div class="answer-line wrong-line"><span>Ваш ответ</span><strong>${safe(q.options[lastAnswer])}</strong></div>`:''}<div class="answer-line correct-line"><span>Правильный ответ</span><strong>${safe(q.options[q.a])}</strong></div><div class="feedback lesson-feedback"><p><strong>Просто:</strong> ${safe(t?.simple||q.why)}</p><p><strong>Почему:</strong> ${safe(q.why)}</p>${t?.example?`<p><strong>Пример:</strong> ${safe(t.example)}</p>`:''}<p><strong>Где используется:</strong> ${safe(termUse(t))}</p></div>`}
function renderTrain(){if(!currentQuiz)currentQuiz=getQuiz();const q=currentQuiz;$("#view-train").innerHTML=`<div class="quiz"><div class="row between"><span class="tag">ВОПРОС ${quizIndex+1}</span><span class="muted small">Выберите один ответ</span></div><div class="card quiz-card"><h2>${q.q}</h2><div>${q.options.map((o,i)=>`<button class="option ${quizAnswered?(i===q.a?'correct':i===lastAnswer?'wrong':''):''}" ${quizAnswered?'disabled':''} onclick="answerQuiz(${i})">${o}</button>`).join("")}</div>${quizAnswered?`${quizFeedback(q)}<button class="btn feedback-next" onclick="nextQuiz()">Следующий вопрос</button>`:""}</div></div>`}
function answerQuiz(i){if(quizAnswered)return;const q=currentQuiz||getQuiz();currentQuiz=q;lastAnswer=i;quizAnswered=true;state.total++;const ok=i===q.a;if(ok)state.correct++;updateSRS(q.termId,ok);setDaily('review');save();renderTrain();renderDashboard()}
function nextQuiz(){if(!quizAnswered)return;quizIndex++;quizAnswered=false;lastAnswer=-1;currentQuiz=null;renderTrain()}

let speakTerm=TERMS[0];
function chooseSpeakTerm(){const candidates=[...dueTerms(),...state.weak.map(term).filter(Boolean)];speakTerm=candidates[0]||TERMS[Math.floor(Math.random()*TERMS.length)]}
function renderSpeak(){if(!speakTerm)chooseSpeakTerm();$("#view-speak").innerHTML=`<div class="grid grid-2"><div class="card voice-card"><span class="tag">ГОЛОСОВОЙ ACTIVE RECALL</span><h2>${speakTerm.word}</h2><p class="muted">${speakTerm.full}</p><h3>Объясните термин своими словами и приведите пример.</h3>${voicePanel('speak')}<div id="speakResult"></div><button class="btn secondary" onclick="newSpeakTerm()">Следующий термин</button></div><div class="card"><h3>После ответа сравните</h3><p><strong>Коротко:</strong> ${speakTerm.simple}</p>${speakTerm.formula?`<p><strong>Формула:</strong> ${speakTerm.formula}</p>`:""}<p><strong>Пример:</strong> ${speakTerm.example||'Сформулируйте собственный пример.'}</p><p><strong>Вопрос инвестора:</strong> ${speakTerm.investor}</p></div></div>`;restoreVoiceTranscript('speak')}
function newSpeakTerm(){chooseSpeakTerm();voiceBuffers.speak="";renderSpeak()}
function evaluateSpeak(text){const low=(text||"").toLowerCase();const base=(speakTerm.word+" "+speakTerm.full+" "+speakTerm.simple+" "+(speakTerm.why||"")).toLowerCase().replace(/[(),—]/g," ");const keywords=[...new Set(base.split(/\s+/).filter(x=>x.length>5))];const hits=keywords.filter(k=>low.includes(k)).length;const score=Math.min(100,25+hits*10+(low.length>100?20:0)+(/\d/.test(low)?10:0));updateSRS(speakTerm.id,score>=70);state.voiceScores.push(score);setDaily('voice');save();const el=$("#speakResult");if(el)el.innerHTML=`<div class="feedback"><strong>Оценка объяснения: ${score}/100</strong><p>${score>=80?'Хорошо: смысл воспроизводится из памяти.':score>=60?'Основа есть. Добавьте пример и связь с решением инвестора.':'Повторите термин через короткий интервал и попробуйте снова без подсказки.'}</p><p class="small"><strong>Эталон:</strong> ${speakTerm.simple}</p></div>`;renderDashboard()}

let pitchTopic="SaaS-стартап";const PITCH_LABELS={problem:"Проблема",solution:"Решение",market:"Рынок",traction:"Traction",model:"Модель",ask:"Запрос"};
function renderPitch(){const p=PITCH_TOPICS[pitchTopic]||Object.values(PITCH_TOPICS)[0];$("#view-pitch").innerHTML=`<div class="grid grid-2"><div class="card"><div class="row between"><div><span class="tag">ГОЛОСОВОЙ PITCH</span><h2>Рассказ о своём проекте</h2></div><select class="input pitch-select" onchange="pitchTopic=this.value;renderPitch()">${Object.keys(PITCH_TOPICS).map(x=>`<option ${x===pitchTopic?'selected':''}>${x}</option>`).join("")}</select></div><p class="muted">Структура — только опора. Сначала посмотрите, затем уберите подсказку и расскажите всё голосом одним заходом.</p><div class="grid">${Object.entries(p).map(([k,v])=>`<div class="card pitch-part"><strong>${PITCH_LABELS[k]||k}</strong><p class="muted">${v}</p></div>`).join("")}</div></div><div class="card voice-card"><h3>Запишите pitch голосом</h3><p class="muted">Нажмите «Начать». Говорите сколько нужно. Текст будет накапливаться. Нажмите «Отправить pitch» — запись остановится и только тогда ответ будет оценён.</p>${voicePanel('pitch')}<div id="pitchScore"></div><div class="small muted pitch-checklist">Проверка: проблема → решение → рынок → traction → бизнес-модель → конкуренция → команда → раунд → использование капитала.</div></div></div>`;restoreVoiceTranscript('pitch')}
function scorePitchText(text){const t=(text||"").toLowerCase();const groups=[["проблем","боль"],["решен","продукт"],["рын","tam","sam"],["traction","retention","mrr","выруч","рост"],["модел","saas","подпис"],["клиент","icp","сегмент"],["конкур","альтернатив"],["команд","основател","опыт"],["раунд","привлека","инвест"],["капитал","средств","runway","milestone"]];const present=groups.map(g=>g.some(k=>t.includes(k)));let score=Math.round(present.filter(Boolean).length/groups.length*85);if(t.length>400)score+=8;if(/\d/.test(t))score+=7;score=Math.min(100,score);state.pitchScores.push(score);state.voiceScores.push(score);save();const missing=["проблема","решение","рынок","traction/цифры","модель","ICP","конкуренция","команда","раунд","use of funds"].filter((_,i)=>!present[i]);const el=$("#pitchScore");if(el)el.innerHTML=`<div class="feedback"><strong>Оценка pitch: ${score}/100</strong><p>${score>=80?'Структура сильная. Теперь сокращайте лишнее и тренируйте ответы на вопросы.':score>=60?'Хорошая основа. Добавьте конкретные цифры и причинную связь.':'Pitch пока больше похож на описание продукта. Нужна инвестиционная логика.'}</p><p class="small"><strong>Не хватает:</strong> ${missing.join(', ')||'ключевые блоки найдены'}.</p></div>`;renderDashboard()}

