// PWA installation/update logic kept intact and update checks remain network-first.
let deferredInstallPrompt=null;const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;const isIOS=()=>/iphone|ipad|ipod/i.test(navigator.userAgent);
function setInstallState(){const b=$("#installApp"),t=$("#installState");if(!b||!t)return;if(isStandalone()){b.hidden=true;t.hidden=false;t.textContent='Приложение установлено'}else{t.hidden=true;b.hidden=false;b.textContent='Установить приложение'}}
addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;setInstallState()});addEventListener('appinstalled',()=>{deferredInstallPrompt=null;setInstallState();toast('Приложение установлено')});
async function installApp(){if(isStandalone()){setInstallState();return}if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;setInstallState();return}openInstallHelp()}
let installModalReturnFocus=null;function openInstallHelp(){installModalReturnFocus=document.activeElement;const m=$("#installModal"),body=$("#installHelpText");if(isIOS())body.innerHTML='<strong>iPhone / iPad:</strong><br>1. Откройте сайт в Safari.<br>2. Нажмите <strong>«Поделиться»</strong>.<br>3. Выберите <strong>«На экран „Домой“»</strong>.<br>4. Подтвердите добавление.';else body.innerHTML='<strong>Android:</strong><br>Откройте меню браузера и выберите <strong>«Установить приложение»</strong> или используйте системную кнопку установки.';m.hidden=false;document.body.classList.add('modal-open');setTimeout(()=>$("#installClose")?.focus(),0)}
function closeInstallHelp(){$("#installModal").hidden=true;document.body.classList.remove('modal-open');if(installModalReturnFocus&&typeof installModalReturnFocus.focus==='function')installModalReturnFocus.focus();installModalReturnFocus=null}$("#installApp")?.addEventListener('click',installApp);$("#installClose")?.addEventListener('click',closeInstallHelp);$("#installModal")?.addEventListener('click',e=>{if(e.target.id==='installModal')closeInstallHelp()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$("#installModal")?.hidden)closeInstallHelp()});setInstallState();
if('serviceWorker' in navigator)addEventListener('load',async()=>{try{const reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});await reg.update();let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()});reg.addEventListener('updatefound',()=>{const w=reg.installing;if(!w)return;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)w.postMessage({type:'SKIP_WAITING'})})})}catch(err){console.error('Service Worker:',err)}});


/* ===== Production learning engine + AI Investor v5 ===== */
state.aiMemory=state.aiMemory||"";
state.aiHistory=state.aiHistory||[];
state.aiWeakTopics=state.aiWeakTopics||[];
state.aiScores=state.aiScores||[];
state.projectProfile=state.projectProfile||{};
state.sessionPlan=state.sessionPlan||{};

function apiBase(){return (localStorage.getItem('investorCoachApiBase')||(window.INVESTOR_COACH_CONFIG&&window.INVESTOR_COACH_CONFIG.apiBase)||'').replace(/\/$/,'')}
function aiReady(){return /^https:\/\//.test(apiBase())}
function saveApiBase(){const el=document.querySelector('#aiApiBase');if(!el)return;const v=el.value.trim().replace(/\/$/,'');if(v&&!/^https:\/\//.test(v)){toast('Нужен HTTPS URL AI-backend.');return}localStorage.setItem('investorCoachApiBase',v);toast(v?'AI-backend сохранён.':'AI-backend отключён.');renderAll()}
function aiStatusHtml(){return aiReady()?'<span class="ai-pill online">● AI подключён</span>':'<span class="ai-pill offline">● Локальный режим</span>'}
function priorityScore(t){const s=srsInfo(t.id),now=new Date(today()+'T12:00:00'),due=new Date((s.due||today())+'T12:00:00');const overdue=Math.max(0,Math.round((now-due)/86400000));const attempts=(s.right||0)+(s.wrong||0);const errorRate=attempts?(s.wrong||0)/attempts:.45;const novelty=attempts?0:1;const weak=state.weak.includes(t.id)?2:0;const aiWeak=state.aiWeakTopics.some(x=>(t.word+' '+t.cat+' '+t.full).toLowerCase().includes(String(x).toLowerCase()))?1.5:0;return overdue*1.6+errorRate*4+novelty*2+weak+aiWeak-(s.box||0)*.7}
buildQuizQueue=function(){return [...QUIZ].sort((a,b)=>priorityScore(term(b.termId)||TERMS[0])-priorityScore(term(a.termId)||TERMS[0]))}
chooseSpeakTerm=function(){speakTerm=[...TERMS].sort((a,b)=>priorityScore(b)-priorityScore(a))[0]||TERMS[0]}
function readinessScore(){const knowledge=mastery();const voice=state.aiScores.length?Math.round(state.aiScores.slice(-10).reduce((a,b)=>a+b,0)/Math.min(10,state.aiScores.length)):(state.voiceScores.length?Math.round(state.voiceScores.slice(-10).reduce((a,b)=>a+b,0)/Math.min(10,state.voiceScores.length)):0);const tests=pct(state.correct,state.total);return Math.round(knowledge*.4+tests*.25+voice*.35)}
function todayPlan(){const due=dueTerms().slice(0,8).map(t=>t.word);const weak=[...TERMS].sort((a,b)=>priorityScore(b)-priorityScore(a)).slice(0,3).map(t=>t.word);return {review:due,newCount:Math.min(4,Math.max(1,8-due.length)),voice:weak[0]||'CAC',investor:state.aiWeakTopics[0]||weak[1]||'unit economics'} }
const _renderDashboardProd=renderDashboard;
renderDashboard=function(){_renderDashboardProd()}

async function aiCoach(mode,text,extra={}){if(!aiReady())throw new Error('AI_NOT_CONFIGURED');const payload={mode,transcript:text,memory:state.aiMemory,history:state.aiHistory.slice(-12),weak_topics:state.aiWeakTopics.slice(0,12),course_day:state.day,project_profile:state.projectProfile,context:extra};const r=await fetch(apiBase()+'/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){const e=await r.text();throw new Error('AI '+r.status+': '+e.slice(0,180))}return r.json()}
function applyAiResult(res,mode,userText){const score=Math.max(0,Math.min(100,Number(res.score)||0));state.aiScores.push(score);state.voiceScores.push(score);state.aiMemory=String(res.memory_summary||state.aiMemory||'').slice(0,6000);state.aiWeakTopics=[...new Set([...(res.focus_topics||[]),...state.aiWeakTopics])].slice(0,20);state.aiHistory.push({role:'user',text:userText.slice(0,5000)},{role:'investor',text:String(res.next_question||res.verdict||'').slice(0,1500)});state.aiHistory=state.aiHistory.slice(-30);save();return score}
function feedbackHtml(res){return `<div class="feedback ai-feedback"><div class="row between"><strong>AI-оценка: ${safe(res.score)}/100</strong><span class="tag">production AI</span></div><p>${safe(res.verdict)}</p>${(res.strengths||[]).length?`<p><strong>Сильные стороны:</strong> ${(res.strengths||[]).map(safe).join(' • ')}</p>`:''}${(res.improvements||[]).length?`<p><strong>Исправить:</strong> ${(res.improvements||[]).map(safe).join(' • ')}</p>`:''}${(res.red_flags||[]).length?`<p><strong>Red flags:</strong> ${(res.red_flags||[]).map(safe).join(' • ')}</p>`:''}${res.model_answer?`<details><summary>Показать сильный вариант ответа</summary><p>${safe(res.model_answer)}</p></details>`:''}</div>`}

const _renderPitchProd=renderPitch;
renderPitch=function(){_renderPitchProd();const card=document.querySelector('#view-pitch .voice-card');if(card){const badge=document.createElement('div');badge.className='ai-mode-line';badge.innerHTML=`${aiStatusHtml()} <span class="small muted">При AI-режиме оценивается смысл, логика, цифры, investor narrative и риски.</span>`;card.prepend(badge)}}
renderInvestor=function(){const msgs=state.messages.length?state.messages:[{who:'ai',text:(state.aiHistory.slice().reverse().find(x=>x.role==='investor')||{}).text||SIM[Math.min(state.simStep,SIM.length-1)].q}];document.querySelector('#view-investor').innerHTML=`<div class="grid grid-2"><div class="card voice-card"><div class="row between"><div><span class="tag">PRODUCTION AI INVESTOR</span><h2>Голосовая встреча с инвестором</h2></div>${aiStatusHtml()}</div><div class="sim-chat" id="simChat">${msgs.map(m=>`<div class="bubble ${m.who}">${safe(m.text)}</div>`).join('')}</div><p class="muted">Нажмите запись, говорите как на реальной встрече и только затем нажмите «Отправить». В AI-режиме вопрос формируется из вашего предыдущего ответа и слабых мест, а не идёт по фиксированному скрипту.</p>${voicePanel('sim')}<div class="row"><button class="btn secondary" onclick="resetSim()">Новая встреча</button></div></div><div class="card"><h3>AI-память и адаптация</h3><p class="muted">Инвестор помнит факты вашего проекта, замечает противоречия и возвращается к слабым темам.</p><div id="simFeedback"><div class="feedback">${state.aiMemory?safe(state.aiMemory):'Память проекта сформируется после первых ответов.'}</div></div>${!aiReady()?`<div class="ai-connect"><h3>Подключить production AI</h3><p class="small muted">GitHub Pages не хранит секретные API-ключи. Разверните backend из папки <code>backend</code> и вставьте его HTTPS URL один раз.</p><input id="aiApiBase" class="input" placeholder="https://investor-coach-ai.YOUR.workers.dev" value="${safe(apiBase())}"><button class="btn" onclick="saveApiBase()">Сохранить AI URL</button></div>`:''}</div></div>`;const chat=document.querySelector('#simChat');if(chat)chat.scrollTop=chat.scrollHeight;restoreVoiceTranscript('sim')}

async function evaluateWithAI(ch,text){const status=document.querySelector('#voiceStatus-'+ch);if(status)status.textContent='AI анализирует ответ…';try{const extra=ch==='speak'?{term:{word:speakTerm.word,definition:speakTerm.simple,example:speakTerm.example,investor:speakTerm.investor}}:ch==='pitch'?{pitch_topic:pitchTopic}:{};const res=await aiCoach(ch,text,extra);const score=applyAiResult(res,ch,text);if(ch==='speak'){updateSRS(speakTerm.id,score>=75);setDaily('voice');const el=document.querySelector('#speakResult');if(el)el.innerHTML=feedbackHtml(res)}else if(ch==='pitch'){state.pitchScores.push(score);const el=document.querySelector('#pitchScore');if(el)el.innerHTML=feedbackHtml(res)}else if(ch==='sim'){state.messages.push({who:'you',text},{who:'ai',text:res.next_question||'Продолжайте.'});setDaily('sim');voiceBuffers.sim='';renderInvestor();setTimeout(()=>{const f=document.querySelector('#simFeedback');if(f)f.innerHTML=feedbackHtml(res)},20)}save();renderDashboard();if(status)status.textContent='Ответ оценён'}catch(e){console.error(e);toast(e.message==='AI_NOT_CONFIGURED'?'AI не подключён — использую локальную оценку.':'AI временно недоступен — использую локальную оценку.');if(ch==='speak')evaluateSpeak(text);if(ch==='pitch')scorePitchText(text);if(ch==='sim')evaluateSim(text)}}

// Real recorder: audio is kept locally until Send, then transcribed server-side.
const mediaState={recorder:null,stream:null,ch:null,chunks:[],startedAt:0};
function cancelVoiceCapture(){try{if(mediaState.recorder&&(mediaState.recorder.state==='recording'||mediaState.recorder.state==='paused'))mediaState.recorder.stop()}catch(_){}try{mediaState.stream?.getTracks().forEach(t=>t.stop())}catch(_){}mediaState.recorder=null;mediaState.stream=null;mediaState.ch=null;mediaState.chunks=[];voiceRunning=false;if(recognition){try{recognition.abort()}catch(_){}}}
function canMediaRecord(){return !!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia&&window.MediaRecorder)}
voicePanel=function(ch){return `<div class="voice-recorder" id="voice-${ch}"><div class="voice-status"><span class="rec-dot"></span><strong id="voiceStatus-${ch}">Готов к записи</strong><small>${aiReady()?'Запись хранится локально и отправляется только после кнопки «Отправить»':'Для точной расшифровки подключите production AI'}</small></div><div class="voice-transcript" id="voiceTranscript-${ch}">${voiceBuffers[ch]||'Во время записи можно говорить свободно. Текст появится после отправки.'}</div><div class="row action-row"><button class="btn" id="voiceStart-${ch}" onclick="toggleVoice('${ch}')">🎙 Начать запись</button><button class="btn send-voice" onclick="submitVoice('${ch}')">➤ Отправить</button></div></div>`}
async function startMediaVoice(ch){if(mediaState.recorder&&mediaState.recorder.state==='recording')return;try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true,channelCount:1}});let mime='';for(const t of ['audio/webm;codecs=opus','audio/mp4','audio/webm']){if(MediaRecorder.isTypeSupported(t)){mime=t;break}}const rec=new MediaRecorder(stream,mime?{mimeType:mime,audioBitsPerSecond:48000}:{audioBitsPerSecond:48000});mediaState.recorder=rec;mediaState.stream=stream;mediaState.ch=ch;mediaState.chunks=[];mediaState.startedAt=Date.now();voiceChannel=ch;voiceRunning=true;rec.ondataavailable=e=>{if(e.data&&e.data.size)mediaState.chunks.push(e.data)};rec.onstop=()=>{voiceRunning=false;setVoiceUI(ch,'Запись готова к отправке',false);stream.getTracks().forEach(t=>t.stop())};rec.start(1000);setVoiceUI(ch,'Идёт запись…',true);const el=document.querySelector('#voiceTranscript-'+ch);if(el)el.textContent='● Запись идёт. Нажмите «Отправить», когда закончите.'}catch(e){console.error(e);toast('Нет доступа к микрофону.');}}
toggleVoice=async function(ch){if(aiReady()&&canMediaRecord()){if(mediaState.recorder&&mediaState.ch===ch&&(mediaState.recorder.state==='recording'||mediaState.recorder.state==='paused')){toast('Чтобы закончить запись, нажмите «Отправить».');return}await startMediaVoice(ch);return}if(voiceRunning&&voiceChannel===ch){toast('Чтобы закончить запись, нажмите «Отправить».');return}startVoice(ch)}
async function transcribeBlob(blob){const fd=new FormData();const ext=blob.type.includes('mp4')?'m4a':'webm';fd.append('file',blob,'answer.'+ext);fd.append('language','ru');const r=await fetch(apiBase()+'/api/transcribe',{method:'POST',body:fd});if(!r.ok)throw new Error('TRANSCRIBE_'+r.status);const j=await r.json();return (j.text||'').trim()}
submitVoice=async function(ch){voiceChannel=ch;if(aiReady()&&mediaState.recorder&&mediaState.ch===ch&&(mediaState.recorder.state==='recording'||mediaState.recorder.state==='paused')){const rec=mediaState.recorder;const done=new Promise(resolve=>rec.addEventListener('stop',resolve,{once:true}));if(rec.state==='paused')rec.resume();rec.stop();await done;const blob=new Blob(mediaState.chunks,{type:rec.mimeType||'audio/webm'});if(blob.size<1000){toast('Запись слишком короткая.');return}setVoiceUI(ch,'Распознаю запись…',false);try{const text=await transcribeBlob(blob);voiceBuffers[ch]=text;const el=document.querySelector('#voiceTranscript-'+ch);if(el)el.textContent=text||'Речь не распознана.';if(!text){toast('Не удалось распознать речь.');return}await evaluateWithAI(ch,text)}catch(e){console.error(e);toast('Не удалось отправить аудио. Проверьте AI-backend.')}finally{mediaState.recorder=null;mediaState.chunks=[]}return}if(voiceRunning&&voiceChannel===ch){voiceStoppingForSend=true;voiceRunning=false;try{recognition.stop()}catch(_){finalSubmit(ch)}}else finalSubmit(ch)}
finalSubmit=async function(ch){const text=(voiceBuffers[ch]||'').trim();if(!text){toast('Сначала запишите голосовой ответ.');return}setVoiceUI(ch,'Ответ отправлен',false);if(aiReady())await evaluateWithAI(ch,text);else{if(ch==='speak')evaluateSpeak(text);if(ch==='pitch')scorePitchText(text);if(ch==='sim')evaluateSim(text)}}
resetSim=function(){state.simStep=0;state.messages=[];state.aiHistory=[];voiceBuffers.sim='';save();renderInvestor()}


// Production Accelerated Coach v7: silent, persistent 1/3/6-hour learning sessions.
state.accel=Object.assign({active:false,targetMin:360,startedAt:0,pausedAt:0,totalPauseMs:0,blockIndex:0,completedBlocks:0,hints:true},state.accel||{});
let accelTicker=null,accelWakeLock=null,lastAccelPhase=-1;
const ACCEL_BLOCK_MIN=20,ACCEL_BREAK_MIN=5;
const ACCEL_TASKS=[
  {view:'learn',title:'Термины',desc:'Короткие карточки и примеры.'},
  {view:'speak',title:'Голосовая практика',desc:'Объясните термин своими словами.'},
  {view:'investor',title:'AI-инвестор',desc:'Отвечайте голосом на вопросы инвестора.'},
  {view:'pitch',title:'Pitch',desc:'Проблема → решение → рынок → traction → ask.'},
  {view:'train',title:'Тесты',desc:'Ответьте и сразу разберите ошибку.'}
];
function accelElapsedMs(){const a=state.accel;if(!a.startedAt)return 0;const end=a.pausedAt||Date.now();return Math.max(0,end-a.startedAt-(a.totalPauseMs||0))}
function accelTargetMs(){return (state.accel.targetMin||360)*60000}
function accelRemainingMs(){return Math.max(0,accelTargetMs()-accelElapsedMs())}
function formatDuration(ms){const total=Math.max(0,Math.floor(ms/1000)),h=Math.floor(total/3600),m=Math.floor((total%3600)/60),sec=total%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${m}:${String(sec).padStart(2,'0')}`}
function accelCyclePosition(){const work=ACCEL_BLOCK_MIN*60000,br=ACCEL_BREAK_MIN*60000,cycle=work+br,pos=accelElapsedMs()%cycle;return {isBreak:pos>=work,remaining:(pos>=work?cycle:work)-pos}}
function accelTask(){const workBlocks=Math.floor(accelElapsedMs()/((ACCEL_BLOCK_MIN+ACCEL_BREAK_MIN)*60000));return ACCEL_TASKS[workBlocks%ACCEL_TASKS.length]}
function accelProgress(){return Math.min(100,Math.round(accelElapsedMs()/Math.max(1,accelTargetMs())*100))}
function accelIsPaused(){return !!state.accel.pausedAt}
function accelStatusText(){if(!state.accel.active)return 'Не запущен';if(accelIsPaused())return 'Пауза';return accelCyclePosition().isBreak?'Перерыв':'Сессия идёт'}
async function requestWakeLock(){if(!state.accel.active||accelIsPaused()||!('wakeLock' in navigator))return;try{if(!accelWakeLock)accelWakeLock=await navigator.wakeLock.request('screen');accelWakeLock.addEventListener?.('release',()=>{accelWakeLock=null})}catch(_){accelWakeLock=null}}
async function releaseWakeLock(){try{await accelWakeLock?.release()}catch(_){}accelWakeLock=null}
function setAccelTarget(min){if(state.accel.active){toast('Сначала завершите текущую сессию.');return}state.accel.targetMin=min;save();refreshAccelUI()}
async function startAccel(min=state.accel.targetMin||360){state.accel={...state.accel,active:true,targetMin:min,startedAt:Date.now(),pausedAt:0,totalPauseMs:0,blockIndex:0,completedBlocks:0,hints:state.accel.hints!==false};save();lastAccelPhase=-1;await requestWakeLock();startAccelTicker();refreshAccelUI();toast('Ускоренный коуч запущен')}
async function pauseAccel(){if(!state.accel.active||accelIsPaused())return;state.accel.pausedAt=Date.now();save();await releaseWakeLock();refreshAccelUI()}
async function resumeAccel(){if(!state.accel.active||!accelIsPaused())return;const now=Date.now();state.accel.totalPauseMs=(state.accel.totalPauseMs||0)+(now-state.accel.pausedAt);state.accel.pausedAt=0;save();await requestWakeLock();refreshAccelUI()}
async function stopAccel(completed=false){if(!state.accel.active)return;state.accel.active=false;state.accel.pausedAt=0;save();await releaseWakeLock();clearInterval(accelTicker);accelTicker=null;refreshAccelUI();toast(completed?'Интенсив завершён':'Сессия завершена')}
function toggleAccelHints(){state.accel.hints=state.accel.hints===false;save();refreshAccelUI()}
function openAccelTask(){if(!state.accel.active)return;go(accelTask().view)}
function accelBlockNumber(){return Math.floor(accelElapsedMs()/((ACCEL_BLOCK_MIN+ACCEL_BREAK_MIN)*60000))+1}
function maybeAdvanceAccel(){if(!state.accel.active||accelIsPaused())return;if(accelRemainingMs()<=0){stopAccel(true);return}const pos=accelCyclePosition(),phase=accelBlockNumber()*2+(pos.isBreak?1:0);if(phase!==lastAccelPhase){lastAccelPhase=phase;refreshAccelUI()}}
function accelCoachHtml(){
 const a=state.accel,pos=a.active?accelCyclePosition():{isBreak:false,remaining:ACCEL_BLOCK_MIN*60000},task=accelTask(),progress=accelProgress(),hints=a.hints!==false;
 const controls=a.active?`<div class="accel-controls-under-clock"><button class="btn secondary" onclick="resumeAccel()" ${!accelIsPaused()?'disabled':''}>Продолжить</button><button class="btn secondary" onclick="pauseAccel()" ${accelIsPaused()?'disabled':''}>Пауза</button><button class="btn" onclick="openAccelTask()">Открыть текущий блок</button><button class="btn secondary" onclick="toggleAccelHints()">${hints?'Скрыть подсказки':'Подсказки'}</button><button class="btn secondary danger-lite" onclick="stopAccel(false)">Завершить</button></div>`:'';
 return `<div class="card accel-coach ${a.active?'running':''}"><div class="accel-head"><div><span class="tag">УСКОРЕННОЕ ОБУЧЕНИЕ</span><h2>Интенсив</h2><p class="muted">1, 3 или 6 часов.</p></div><div class="accel-clock"><strong>${a.active?formatDuration(accelRemainingMs()):formatDuration(accelTargetMs())}</strong><small>${a.active?'осталось':'план'}</small>${controls}</div></div><div class="accel-targets">${[[60,'1 час'],[180,'3 часа'],[360,'6 часов']].map(([m,l])=>`<button class="${a.targetMin===m?'active':''}" onclick="setAccelTarget(${m})" ${a.active?'disabled':''}>${l}</button>`).join('')}</div>${a.active?`<div class="accel-live"><div class="row between"><strong>${accelStatusText()} · блок ${accelBlockNumber()}</strong><span>${progress}%</span></div><div class="progress"><div style="width:${progress}%"></div></div>${hints?`<div class="accel-task"><span>${pos.isBreak?'☕':'•'}</span><div><strong>${pos.isBreak?'Короткий перерыв':safe(task.title)}</strong><p>${pos.isBreak?'Можно сделать паузу, пройтись или сразу открыть следующий блок.':safe(task.desc)}</p><small>До следующего блока: ${formatDuration(pos.remaining)}</small></div></div>`:''}</div>`:`<div class="accel-preview"><p class="muted">Можно остановить и продолжить позже.</p><button class="btn accel-start" onclick="startAccel(${a.targetMin||360})">Запустить ускоренный коуч</button></div>`}</div>`
}
function refreshAccelUI(){document.querySelectorAll('[data-accel-slot]').forEach(el=>el.innerHTML=accelCoachHtml());if(state.accel.active&&!accelIsPaused())requestWakeLock()}
function startAccelTicker(){clearInterval(accelTicker);if(!state.accel.active)return;accelTicker=setInterval(()=>{maybeAdvanceAccel();refreshAccelUI()},1000);maybeAdvanceAccel()}

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.accel.active&&!accelIsPaused())requestWakeLock()});


// Enterprise pilot foundation: measurable competency assessment + learner report.
const ENTERPRISE_COMPETENCIES=[
 {id:"metrics",name:"Метрики и unit economics",cats:["Метрики","Финансы"]},
 {id:"market",name:"Рынок и PMF",cats:["Рынок"]},
 {id:"growth",name:"GTM и рост",cats:["Рост","Бизнес"]},
 {id:"fundraising",name:"Fundraising и сделка",cats:["Фандрайзинг","Право"]},
 {id:"communication",name:"Investor communication",cats:["Коммуникация"]}
];
let enterpriseAssessment=null;
function enterpriseProfileComplete(){return !!(state.enterprise.orgName&&state.enterprise.learnerName)}
function setEnterpriseField(k,v){state.enterprise[k]=String(v||'').trim().slice(0,120);save()}
function competencyScore(comp){const terms=TERMS.filter(t=>comp.cats.includes(t.cat));if(!terms.length)return 0;return Math.round(terms.reduce((sum,t)=>{const s=state.srs[t.id]||{};const coach=state.coachStats[t.id]||{};const srs=Math.min(100,((s.box||0)/5)*100);const ctot=(coach.right||0)+(coach.wrong||0);const c=ctot?Math.round((coach.right||0)/ctot*100):0;return sum+(ctot?Math.round(srs*.45+c*.55):srs)},0)/terms.length)}
function competencyLevel(score){return score>=85?'Investor-ready':score>=70?'Уверенный':score>=50?'Рабочий':score>=25?'Базовый':'Начальный'}
function enterpriseReadiness(){const scores=ENTERPRISE_COMPETENCIES.map(competencyScore);return Math.round(scores.reduce((a,b)=>a+b,0)/scores.length)}
function assessmentPool(){const seen=new Set(),out=[];for(const c of ENTERPRISE_COMPETENCIES){const qs=QUIZ.filter(q=>{const t=term(q.termId);return t&&c.cats.includes(t.cat)}).slice(0,3);for(const q of qs){const key=q.termId+'|'+q.q;if(!seen.has(key)){seen.add(key);out.push({...q,competency:c.id})}}}return out.slice(0,12)}
function startEnterpriseAssessment(kind='baseline'){const qs=assessmentPool();enterpriseAssessment={kind,index:0,answers:[],questions:qs,answered:false,selected:null};renderOrg();pushAppHistory('org',{assessment:true,index:0})}
function answerEnterpriseAssessment(i){if(!enterpriseAssessment||enterpriseAssessment.answered)return;const q=enterpriseAssessment.questions[enterpriseAssessment.index];enterpriseAssessment.selected=i;enterpriseAssessment.answered=true;enterpriseAssessment.answers.push({competency:q.competency,ok:i===q.a,termId:q.termId});renderOrg()}
function nextEnterpriseAssessment(){if(!enterpriseAssessment)return;enterpriseAssessment.index++;enterpriseAssessment.answered=false;enterpriseAssessment.selected=null;if(enterpriseAssessment.index>=enterpriseAssessment.questions.length){finishEnterpriseAssessment();return}renderOrg();pushAppHistory('org',{assessment:true,index:enterpriseAssessment.index})}
function finishEnterpriseAssessment(){const a=enterpriseAssessment,by={};for(const c of ENTERPRISE_COMPETENCIES)by[c.id]={right:0,total:0};for(const x of a.answers){by[x.competency].total++;if(x.ok)by[x.competency].right++}const total=a.answers.length,right=a.answers.filter(x=>x.ok).length;const record={id:Date.now(),kind:a.kind,date:new Date().toISOString(),score:pct(right,total),by:Object.fromEntries(Object.entries(by).map(([k,v])=>[k,pct(v.right,v.total)]))};state.enterprise.assessments.push(record);save();enterpriseAssessment=null;renderOrg();toast('Диагностика сохранена')}
function latestAssessment(kind){return [...state.enterprise.assessments].reverse().find(a=>a.kind===kind)}
function enterpriseImprovement(){const b=latestAssessment('baseline'),f=latestAssessment('final');return b&&f?f.score-b.score:null}
function csvEscape(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function exportEnterpriseCSV(){const rows=[["Организация","Сотрудник","Роль","Дата","Тип","Итог,%",...ENTERPRISE_COMPETENCIES.map(c=>c.name)]];for(const a of state.enterprise.assessments){rows.push([state.enterprise.orgName,state.enterprise.learnerName,state.enterprise.role,new Date(a.date).toLocaleDateString('ru-RU'),a.kind==='baseline'?'До обучения':'После обучения',a.score,...ENTERPRISE_COMPETENCIES.map(c=>a.by[c.id]??0)])}if(!state.enterprise.assessments.length){rows.push([state.enterprise.orgName,state.enterprise.learnerName,state.enterprise.role,new Date().toLocaleDateString('ru-RU'),'Текущий прогресс',enterpriseReadiness(),...ENTERPRISE_COMPETENCIES.map(competencyScore)])}const blob=new Blob([rows.map(r=>r.map(csvEscape).join(';')).join('\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='investor-coach-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function assessmentCard(a,label){if(!a)return `<div class="enterprise-assessment-empty"><strong>${label}</strong><span>Не пройдена</span></div>`;return `<div class="enterprise-assessment-result"><strong>${label}</strong><span>${a.score}%</span><small>${new Date(a.date).toLocaleDateString('ru-RU')}</small></div>`}
function renderOrg(){const root=$('#view-org');if(!root)return;if(enterpriseAssessment){const a=enterpriseAssessment,q=a.questions[a.index],n=a.index+1,t=term(q.termId);root.innerHTML=`<div class="quiz"><div class="row between"><button class="btn secondary" onclick="enterpriseAssessment=null;renderOrg()">← Выйти</button><span class="muted small">${n}/${a.questions.length}</span></div><div class="card quiz-card"><span class="tag">${a.kind==='baseline'?'ДИАГНОСТИКА ДО ОБУЧЕНИЯ':'ИТОГОВАЯ ДИАГНОСТИКА'}</span><h2>${safe(q.q)}</h2><div>${q.options.map((o,i)=>`<button class="option ${a.answered?(i===q.a?'correct':i===a.selected?'wrong':''):''}" ${a.answered?'disabled':''} onclick="answerEnterpriseAssessment(${i})">${safe(o)}</button>`).join('')}</div>${a.answered?`<div class="lesson-feedback feedback"><p><strong>Правильный ответ:</strong> ${safe(q.options[q.a])}</p><p><strong>Почему:</strong> ${safe(q.why||t?.simple||'')}</p></div><button class="btn feedback-next" onclick="nextEnterpriseAssessment()">${n===a.questions.length?'Завершить':'Следующий вопрос'}</button>`:''}</div></div>`;return}
 const base=latestAssessment('baseline'),final=latestAssessment('final'),impr=enterpriseImprovement(),ready=enterpriseReadiness();
 root.innerHTML=`<div class="grid grid-2"><div class="card"><span class="tag">CORPORATE PILOT</span><h2>Профиль обучения</h2><label class="field-label">Организация<input class="input" value="${safe(state.enterprise.orgName)}" placeholder="Название компании" oninput="setEnterpriseField('orgName',this.value)"></label><label class="field-label">Сотрудник<input class="input" value="${safe(state.enterprise.learnerName)}" placeholder="Имя сотрудника" oninput="setEnterpriseField('learnerName',this.value)"></label><label class="field-label">Роль<input class="input" value="${safe(state.enterprise.role)}" placeholder="Например: Business Development" oninput="setEnterpriseField('role',this.value)"></label><p class="muted small">Данные пока сохраняются локально на этом устройстве. Для корпоративного deployment следующим слоем подключается защищённая серверная учётная запись.</p></div><div class="card"><span class="tag">INVESTOR READINESS</span><div class="enterprise-score">${ready}%</div><p><strong>${competencyLevel(ready)}</strong></p><p class="muted">Оценка строится из реальной практики Coach и интервального закрепления, а не из времени в приложении.</p><button class="btn secondary" onclick="exportEnterpriseCSV()">Экспорт отчёта CSV</button></div></div>
 <h2 class="section-title">Компетенции</h2><div class="grid grid-2 enterprise-competencies">${ENTERPRISE_COMPETENCIES.map(c=>{const s=competencyScore(c);return `<div class="card"><div class="row between"><strong>${safe(c.name)}</strong><span>${s}%</span></div><div class="progress"><div style="width:${s}%"></div></div><small class="muted">${competencyLevel(s)}</small></div>`}).join('')}</div>
 <h2 class="section-title">Измерение результата</h2><div class="card"><div class="enterprise-assessments">${assessmentCard(base,'До обучения')}${assessmentCard(final,'После обучения')}${impr!==null?`<div class="enterprise-improvement"><strong>${impr>=0?'+':''}${impr} п.п.</strong><span>изменение результата</span></div>`:''}</div><div class="row enterprise-actions"><button class="btn" onclick="startEnterpriseAssessment('baseline')">Диагностика до обучения</button><button class="btn secondary" onclick="startEnterpriseAssessment('final')">Итоговая диагностика</button></div><p class="muted small">Одинаковая структура компетенций позволяет сравнить baseline и результат после курса.</p></div>`}

// Make installation an explicit website CTA while preserving the standard PWA prompt and iOS instructions.
function installCtaHtml(){return `<div class="card install-cta"><div><span class="tag">PWA ДЛЯ ТЕЛЕФОНА</span><h2>Investor Coach как приложение</h2><p class="muted">Установите сайт на телефон: отдельная иконка, standalone-режим и офлайн-доступ к основным материалам.</p></div><button class="btn install-download" onclick="installApp()">⬇ Скачать приложение</button></div>`}
const _renderDashboardV6=renderDashboard;
renderDashboard=function(){_renderDashboardV6();const root=document.querySelector('#view-dashboard');if(root){const top=document.createElement('div');top.className='v6-dashboard-top';top.innerHTML=installCtaHtml()+`<div data-accel-slot>${accelCoachHtml()}</div>`;root.prepend(top)}setInstallState()}
const _renderRoadmapV6=renderRoadmap;
renderRoadmap=function(){_renderRoadmapV6();const root=document.querySelector('#view-roadmap');if(root){const slot=document.createElement('div');slot.setAttribute('data-accel-slot','');slot.innerHTML=accelCoachHtml();root.prepend(slot)}}
const _setInstallStateV6=setInstallState;
setInstallState=function(){_setInstallStateV6();document.querySelectorAll('.install-download').forEach(b=>{if(isStandalone()){b.textContent='✓ Приложение установлено';b.disabled=true}else{b.textContent='⬇ Скачать приложение';b.disabled=false}})}

if(state.accel.active){if(state.accel.pausedAt&&state.accel.pausedAt<state.accel.startedAt)state.accel.pausedAt=0;startAccelTicker()}

renderAll();

/* ===== Enterprise accounts + cloud sync v8.5 ===== */
const enterpriseSession={token:localStorage.getItem('icEnterpriseToken')||'',user:null,team:[],assignments:[],dashboard:null,audit:[],sso:null,scim:null,busy:false,lastSync:'',ssoExchangeBusy:false};
function enterpriseCloudReady(){return aiReady()}
const ENTERPRISE_PERMISSIONS={
 admin:new Set(['team:view','team:roles','team:sessions','invite:learner','invite:manager','assignment:view','assignment:create','dashboard:view','audit:view','sso:view','sso:manage','scim:view','scim:manage','reports:view','reports:export']),
 manager:new Set(['team:view','invite:learner','assignment:view','assignment:create','dashboard:view','reports:view','reports:export']),
 learner:new Set(['assignment:view'])
};
function enterpriseCan(permission){const role=enterpriseSession.user?.role||'learner';return ENTERPRISE_PERMISSIONS[role]?.has(permission)||false}
function enterpriseRoleLabel(role){return role==='admin'?'Администратор':role==='manager'?'Менеджер':'Сотрудник'}
async function enterpriseApi(path,{method='GET',body,auth=true}={}){if(!enterpriseCloudReady())throw new Error('Сначала подключите HTTPS backend в настройках AI.');const h={};if(body!==undefined)h['Content-Type']='application/json';if(auth&&enterpriseSession.token)h.Authorization='Bearer '+enterpriseSession.token;const r=await fetch(apiBase()+path,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body)});let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.message||({invalid_credentials:'Неверный email или пароль.',unauthorized:'Сессия истекла. Войдите снова.',email_exists:'Этот email уже зарегистрирован.',invalid_invite:'Код приглашения недействителен или истёк.',database_not_configured:'Корпоративная база данных ещё не настроена.',forbidden:'Недостаточно прав для этого действия.',cannot_change_self:'Нельзя изменить собственную роль администратора.',invalid_role:'Недопустимая роль.',sso_invalid:'Проверьте параметры OIDC.',sso_not_found:'Для этого email-домена SSO не настроен.',sso_expired:'SSO-сессия истекла. Начните вход заново.',sso_failed:'Корпоративный SSO-вход не выполнен.'}[j.error])||'Ошибка сервера');return j}
function setEnterpriseSession(j){enterpriseSession.token=j.token||enterpriseSession.token;enterpriseSession.user=j.user||enterpriseSession.user;if(j.token)localStorage.setItem('icEnterpriseToken',j.token);if(j.user){state.enterprise.orgName=j.user.orgName||state.enterprise.orgName;state.enterprise.learnerName=j.user.name||state.enterprise.learnerName;state.enterprise.role=j.user.role||state.enterprise.role;save()}}
async function enterpriseSsoStart(){const email=$('#corpSsoEmail')?.value.trim().toLowerCase();if(!email){toast('Введите рабочий email');return}try{const returnUrl=location.origin+location.pathname;const j=await enterpriseApi('/api/account/sso/start',{method:'POST',auth:false,body:{email,returnUrl}});if(!j.authorizationUrl)throw new Error('SSO URL не получен');location.href=j.authorizationUrl}catch(e){toast(e.message)}}
async function enterpriseSsoExchange(){if(enterpriseSession.ssoExchangeBusy)return;const u=new URL(location.href),code=u.searchParams.get('sso_code');if(!code)return;enterpriseSession.ssoExchangeBusy=true;try{const j=await enterpriseApi('/api/account/sso/exchange',{method:'POST',auth:false,body:{code}});setEnterpriseSession(j);u.searchParams.delete('sso_code');history.replaceState(history.state,'',u.pathname+u.search+u.hash);await enterprisePullState(true);await enterpriseRefreshCompany();toast('Корпоративный SSO-вход выполнен');renderOrg()}catch(e){u.searchParams.delete('sso_code');history.replaceState(history.state,'',u.pathname+u.search+u.hash);toast(e.message)}finally{enterpriseSession.ssoExchangeBusy=false}}
async function enterpriseRegister(){const orgName=$('#corpOrg')?.value.trim(),name=$('#corpName')?.value.trim(),email=$('#corpEmail')?.value.trim(),password=$('#corpPassword')?.value||'';try{enterpriseSession.busy=true;setEnterpriseSession(await enterpriseApi('/api/account/register-org',{method:'POST',auth:false,body:{orgName,name,email,password}}));await enterprisePushState();toast('Корпоративный аккаунт создан');renderOrg()}catch(e){toast(e.message)}finally{enterpriseSession.busy=false}}
async function enterpriseLogin(){const email=$('#corpLoginEmail')?.value.trim(),password=$('#corpLoginPassword')?.value||'';try{enterpriseSession.busy=true;setEnterpriseSession(await enterpriseApi('/api/account/login',{method:'POST',auth:false,body:{email,password}}));await enterprisePullState(true);await enterpriseRefreshCompany();toast('Вход выполнен');renderOrg()}catch(e){toast(e.message)}finally{enterpriseSession.busy=false}}
async function enterpriseJoin(){const code=$('#corpJoinCode')?.value.trim(),name=$('#corpJoinName')?.value.trim(),email=$('#corpJoinEmail')?.value.trim(),password=$('#corpJoinPassword')?.value||'';try{enterpriseSession.busy=true;setEnterpriseSession(await enterpriseApi('/api/account/join',{method:'POST',auth:false,body:{code,name,email,password}}));await enterprisePushState(true);await enterpriseRefreshCompany();toast('Вы присоединились к компании');renderOrg()}catch(e){toast(e.message)}finally{enterpriseSession.busy=false}}
async function enterpriseLogout(){try{await enterpriseApi('/api/account/logout',{method:'POST'})}catch{}enterpriseSession.token='';enterpriseSession.user=null;enterpriseSession.team=[];enterpriseSession.assignments=[];enterpriseSession.dashboard=null;enterpriseSession.audit=[];enterpriseSession.sso=null;enterpriseSession.scim=null;localStorage.removeItem('icEnterpriseToken');renderOrg()}
async function enterpriseRestore(){if(!enterpriseSession.token||!enterpriseCloudReady())return;try{const j=await enterpriseApi('/api/account/me');enterpriseSession.user=j.user;await enterpriseRefreshCompany();renderOrg()}catch{enterpriseSession.token='';localStorage.removeItem('icEnterpriseToken')}}
async function enterprisePushState(silent=false){if(!enterpriseSession.token||!enterpriseCloudReady())return;try{const copy=JSON.parse(JSON.stringify(state));delete copy.aiMemory;delete copy.aiHistory;await enterpriseApi('/api/account/state',{method:'POST',body:{state:copy}});enterpriseSession.lastSync=new Date().toISOString();if(!silent)toast('Прогресс сохранён в компании')}catch(e){if(!silent)toast(e.message)}}
async function enterprisePullState(merge=false){if(!enterpriseSession.token||!enterpriseCloudReady())return;try{const j=await enterpriseApi('/api/account/state');if(!j.state)return;if(merge){const remote=j.state;for(const k of ['learned','srs','coachStats','daily'])state[k]=Object.assign({},state[k]||{},remote[k]||{});for(const k of ['correct','total','day','streak'])state[k]=Math.max(Number(state[k]||0),Number(remote[k]||0));if((remote.enterprise?.assessments||[]).length>(state.enterprise.assessments||[]).length)state.enterprise.assessments=remote.enterprise.assessments}else Object.assign(state,j.state);save();enterpriseSession.lastSync=j.updatedAt||'';renderAll()}catch(e){toast(e.message)}}
async function enterpriseInvite(role='learner'){if(role==='manager'&&!enterpriseCan('invite:manager')){toast('Назначать менеджеров может только администратор');return}if(role==='learner'&&!enterpriseCan('invite:learner'))return;try{const j=await enterpriseApi('/api/account/invite',{method:'POST',body:{role}});await navigator.clipboard?.writeText(j.code);prompt(`Код приглашения · ${enterpriseRoleLabel(j.role)} · действует 7 дней:`,j.code);await enterpriseLoadAudit();renderOrg()}catch(e){toast(e.message)}}
async function enterpriseLoadTeam(){if(!enterpriseSession.user||!['admin','manager'].includes(enterpriseSession.user.role))return;try{enterpriseSession.team=(await enterpriseApi('/api/account/team')).members||[]}catch{enterpriseSession.team=[]}}
async function enterpriseLoadAssignments(){if(!enterpriseSession.user)return;try{enterpriseSession.assignments=(await enterpriseApi('/api/account/assignments')).assignments||[]}catch{enterpriseSession.assignments=[]}}
async function enterpriseLoadDashboard(){if(!enterpriseCan('dashboard:view')){enterpriseSession.dashboard=null;return}try{enterpriseSession.dashboard=(await enterpriseApi('/api/account/dashboard')).metrics||null}catch{enterpriseSession.dashboard=null}}
async function enterpriseLoadAudit(){if(!enterpriseCan('audit:view')){enterpriseSession.audit=[];return}try{enterpriseSession.audit=(await enterpriseApi('/api/account/audit')).events||[]}catch{enterpriseSession.audit=[]}}
async function enterpriseLoadSso(){if(!enterpriseCan('sso:view')){enterpriseSession.sso=null;return}try{enterpriseSession.sso=(await enterpriseApi('/api/account/sso')).sso||null}catch{enterpriseSession.sso=null}}
async function enterpriseLoadScim(){if(!enterpriseCan('scim:view')){enterpriseSession.scim=null;return}try{enterpriseSession.scim=(await enterpriseApi('/api/account/scim/token')).scim||null}catch{enterpriseSession.scim=null}}
async function enterpriseRefreshCompany(){await Promise.all([enterpriseLoadTeam(),enterpriseLoadAssignments(),enterpriseLoadDashboard(),enterpriseLoadAudit(),enterpriseLoadSso(),enterpriseLoadScim()]);renderOrg()}
function enterpriseDefaultDue(){const d=new Date();d.setDate(d.getDate()+30);return d.toISOString().slice(0,10)}
function assignmentPlanLabel(p){return p==='7'?'7 дней · ускоренный':p==='365'?'1 год · закрепление':'30 дней · системный'}
function assignmentStatus(a){if(a.status==='completed')return 'Завершено';if(new Date(a.dueAt).getTime()<Date.now())return 'Просрочено';return 'Назначено'}
function enterpriseApplyAssignment(id){const a=enterpriseSession.assignments.find(x=>x.id===id);if(!a)return;state.coachPlan=String(a.plan||'30');state.coachPlanDays=state.coachPlanDays||{'7':1,'30':1,'365':1};save();go('coach');toast('Программа Coach выбрана')}
async function enterpriseCreateAssignment(){const userId=$('#assignUser')?.value,plan=$('#assignPlan')?.value||'30',dueAt=$('#assignDue')?.value,targetScore=Number($('#assignTarget')?.value||80);if(!userId||!dueAt){toast('Выберите сотрудника и дедлайн');return}try{await enterpriseApi('/api/account/assignments',{method:'POST',body:{userId,plan,dueAt:new Date(dueAt+'T23:59:59').toISOString(),targetScore}});toast('Программа назначена');await enterpriseRefreshCompany()}catch(e){toast(e.message)}}

async function enterpriseChangeRole(userId,role){if(!enterpriseCan('team:roles'))return;const member=enterpriseSession.team.find(x=>x.id===userId);if(!member||member.role===role)return;if(!confirm(`Изменить роль ${member.name} на «${enterpriseRoleLabel(role)}»?`))return;try{await enterpriseApi('/api/account/team/role',{method:'POST',body:{userId,role}});toast('Роль обновлена');await enterpriseRefreshCompany()}catch(e){toast(e.message)}}
async function enterpriseRevokeSessions(userId){if(!enterpriseCan('team:sessions'))return;const member=enterpriseSession.team.find(x=>x.id===userId);if(!member)return;if(!confirm(`Завершить все активные сессии сотрудника ${member.name}?`))return;try{await enterpriseApi('/api/account/team/revoke-sessions',{method:'POST',body:{userId}});toast('Сессии завершены');await enterpriseLoadAudit();renderOrg()}catch(e){toast(e.message)}}
async function enterpriseSaveSso(){if(!enterpriseCan('sso:manage'))return;const issuer=$('#ssoIssuer')?.value.trim(),clientId=$('#ssoClientId')?.value.trim(),emailDomain=$('#ssoDomain')?.value.trim().toLowerCase(),enabled=!!$('#ssoEnabled')?.checked;try{const j=await enterpriseApi('/api/account/sso',{method:'POST',body:{provider:'oidc',issuer,clientId,emailDomain,enabled}});enterpriseSession.sso=j.sso;toast('SSO-конфигурация сохранена');await enterpriseLoadAudit();renderOrg()}catch(e){toast(e.message)}}
function enterpriseSsoHtml(){if(!enterpriseCan('sso:view'))return '';const s=enterpriseSession.sso||{};return `<h2 class="section-title">SSO · OIDC</h2><div class="card"><div class="row between"><div><strong>Корпоративная идентификация</strong><p class="muted small">Конфигурация готовит организацию к OIDC. Client secret не хранится в браузере или D1 — он задаётся только как Worker secret при подключении конкретного IdP.</p></div><span class="tag">${s.enabled?'НАСТРОЕНО':'НЕ НАСТРОЕНО'}</span></div><label class="field-label">Issuer URL<input id="ssoIssuer" class="input" type="url" placeholder="https://login.company.com/..." value="${safe(s.issuer||'')}"></label><label class="field-label">Client ID<input id="ssoClientId" class="input" placeholder="OIDC client id" value="${safe(s.clientId||'')}"></label><label class="field-label">Разрешённый email-домен<input id="ssoDomain" class="input" placeholder="company.com" value="${safe(s.emailDomain||'')}"></label><label class="row"><input id="ssoEnabled" type="checkbox" ${s.enabled?'checked':''}> <span>Конфигурация активна</span></label><button class="btn secondary" onclick="enterpriseSaveSso()">Сохранить SSO-конфигурацию</button></div>`}
async function enterpriseCreateScimToken(){if(!enterpriseCan('scim:manage'))return;if(!confirm('Создать новый SCIM token? Если token уже существует, старый будет отозван.'))return;try{const j=await enterpriseApi('/api/account/scim/token',{method:'POST',body:{}});enterpriseSession.scim=j.scim;prompt('SCIM Bearer token показывается только один раз. Сохраните его в Identity Provider:',j.token);await enterpriseLoadAudit();renderOrg()}catch(e){toast(e.message)}}
async function enterpriseRevokeScimToken(){if(!enterpriseCan('scim:manage')||!enterpriseSession.scim?.active)return;if(!confirm('Отозвать SCIM token? Автоматическое provisioning остановится.'))return;try{await enterpriseApi('/api/account/scim/token',{method:'DELETE'});enterpriseSession.scim={active:false};await enterpriseLoadAudit();toast('SCIM token отозван');renderOrg()}catch(e){toast(e.message)}}
function enterpriseScimHtml(){if(!enterpriseCan('scim:view'))return '';const x=enterpriseSession.scim||{};return `<h2 class="section-title">SCIM provisioning</h2><div class="card"><div class="row between"><div><strong>Автоматическое управление сотрудниками</strong><p class="muted small">SCIM 2.0 endpoint: <code>${safe(apiBase())}/scim/v2</code>. Token хранится на стороне Identity Provider; в базе сохраняется только SHA-256 hash.</p></div><span class="tag">${x.active?'АКТИВЕН':'НЕ НАСТРОЕН'}</span></div><div class="row">${x.active?`<button class="btn secondary" onclick="enterpriseRevokeScimToken()">Отозвать token</button>`:`<button class="btn secondary" onclick="enterpriseCreateScimToken()">Создать SCIM token</button>`}</div>${x.createdAt?`<p class="muted small">Создан: ${new Date(x.createdAt).toLocaleString('ru-RU')}</p>`:''}</div>`}
const ENTERPRISE_AUDIT_LABELS={organization_created:'Создана организация',auth_login:'Вход в аккаунт',auth_logout:'Выход из аккаунта',member_joined:'Сотрудник присоединился',invite_created:'Создано приглашение',assignment_created:'Назначено обучение',assignment_completed:'Обучение завершено',role_changed:'Изменена роль',sessions_revoked:'Сессии пользователя завершены',sso_updated:'Изменена SSO-конфигурация',scim_token_created:'Создан SCIM token',scim_token_revoked:'Отозван SCIM token',scim_user_created:'SCIM создал сотрудника',scim_user_updated:'SCIM обновил сотрудника',scim_user_deactivated:'SCIM деактивировал сотрудника'};
function enterpriseAuditHtml(){if(!enterpriseCan('audit:view'))return '';const events=enterpriseSession.audit||[];return `<h2 class="section-title">Журнал действий</h2><div class="card"><div class="enterprise-team">${events.length?events.map(e=>`<div class="row between enterprise-member"><div><strong>${safe(ENTERPRISE_AUDIT_LABELS[e.action]||e.action)}</strong><small class="muted">${safe(e.actor||'system')} · ${new Date(e.createdAt).toLocaleString('ru-RU')}</small></div><span class="tag">${safe(e.targetType||'system')}</span></div>`).join(''):'Событий пока нет.'}</div></div>`}


async function enterpriseDownloadReport(type='learners'){if(!enterpriseCan('reports:export'))return;const allowed=['learners','assignments','audit'];if(!allowed.includes(type)||(type==='audit'&&!enterpriseCan('audit:view')))return;try{const base=apiBase(),url=`${base}/api/account/reports/export?type=${encodeURIComponent(type)}`;const r=await fetch(url,{headers:{Authorization:`Bearer ${enterpriseSession.token}`}});if(!r.ok){let j={};try{j=await r.json()}catch{}throw new Error(j.message||'Не удалось сформировать отчёт')}const blob=await r.blob(),cd=r.headers.get('Content-Disposition')||'',m=cd.match(/filename="?([^"]+)"?/i),name=m?.[1]||`investor-coach-${type}.csv`,a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);await enterpriseLoadAudit();toast('Отчёт сформирован')}catch(e){toast(e.message)}}
function enterpriseReportsHtml(){if(!enterpriseCan('reports:view'))return '';return `<h2 class="section-title">Отчёты HR / L&D</h2><div class="card"><p class="muted small">Экспортируются только реальные серверные данные организации. Отчёты не содержат аудиозаписи и AI-prompts.</p><div class="row enterprise-actions"><button class="btn secondary" onclick="enterpriseDownloadReport('learners')">Сотрудники · CSV</button><button class="btn secondary" onclick="enterpriseDownloadReport('assignments')">Назначения · CSV</button>${enterpriseCan('audit:view')?`<button class="btn secondary" onclick="enterpriseDownloadReport('audit')">Audit · CSV</button>`:''}</div></div>`}
function enterpriseManagerDashboardHtml(){const d=enterpriseSession.dashboard;if(!d)return '';const metric=(v,suffix='')=>v==null?'—':safe(v)+suffix;return `<h2 class="section-title">Панель руководителя</h2><div class="grid grid-4 enterprise-kpis"><div class="card"><small class="muted">Сотрудники</small><strong>${metric(d.members)}</strong></div><div class="card"><small class="muted">Активны 7 дней</small><strong>${metric(d.active7d)}</strong></div><div class="card"><small class="muted">Итоговая диагностика</small><strong>${metric(d.finalCompleted)} / ${metric(d.members)}</strong></div><div class="card"><small class="muted">Средний итог</small><strong>${metric(d.avgFinal,'%')}</strong></div><div class="card"><small class="muted">Средний тест</small><strong>${metric(d.avgTestScore,'%')}</strong></div><div class="card"><small class="muted">Coach · терминов</small><strong>${metric(d.avgCoachTerms)}</strong></div><div class="card"><small class="muted">Назначено</small><strong>${metric(d.assignmentsActive)}</strong></div><div class="card"><small class="muted">Просрочено</small><strong>${metric(d.assignmentsOverdue)}</strong></div></div>`}
function enterpriseAssignmentsHtml(){const list=enterpriseSession.assignments||[],u=enterpriseSession.user;if(!u)return '';if(['admin','manager'].includes(u.role)){const learners=(enterpriseSession.team||[]).filter(m=>m.role==='learner');return `${enterpriseManagerDashboardHtml()}<h2 class="section-title">Назначить обучение</h2><div class="card enterprise-assignment-form"><select id="assignUser" class="input"><option value="">Сотрудник</option>${learners.map(m=>`<option value="${safe(m.id)}">${safe(m.name)} · ${safe(m.email)}</option>`).join('')}</select><select id="assignPlan" class="input"><option value="7">7 дней · ускоренный</option><option value="30" selected>30 дней · системный</option><option value="365">1 год · закрепление</option></select><input id="assignDue" class="input" type="date" value="${enterpriseDefaultDue()}"><input id="assignTarget" class="input" type="number" min="50" max="100" value="80" aria-label="Целевой балл"><button class="btn" onclick="enterpriseCreateAssignment()">Назначить</button></div><h2 class="section-title">Назначения</h2><div class="card enterprise-assignment-list">${list.length?list.map(x=>`<div class="enterprise-assignment row between"><div><strong>${safe(x.userName||'Сотрудник')}</strong><small class="muted">${assignmentPlanLabel(x.plan)} · до ${new Date(x.dueAt).toLocaleDateString('ru-RU')} · цель ${x.targetScore}%</small></div><span class="tag ${assignmentStatus(x)==='Просрочено'?'danger-tag':''}">${assignmentStatus(x)}</span></div>`).join(''):'Назначений пока нет.'}</div>`}return `<h2 class="section-title">Моя программа</h2><div class="card enterprise-assignment-list">${list.length?list.map(x=>`<div class="enterprise-assignment"><div class="row between"><div><strong>${assignmentPlanLabel(x.plan)}</strong><small class="muted">До ${new Date(x.dueAt).toLocaleDateString('ru-RU')} · целевой итог ${x.targetScore}%</small></div><span class="tag">${assignmentStatus(x)}</span></div>${x.status!=='completed'?`<button class="btn secondary" onclick="enterpriseApplyAssignment('${safe(x.id)}')">Открыть в Coach</button>`:''}</div>`).join(''):'Компания пока не назначила программу.'}</div>`}

function enterpriseAccountHtml(){if(!enterpriseCloudReady())return `<div class="card"><span class="tag">CORPORATE CLOUD</span><h2>Серверная синхронизация</h2><p class="muted">Корпоративный backend ещё не подключён. Локальное обучение продолжает работать.</p></div>`;if(!enterpriseSession.user)return `<div class="grid grid-2"><div class="card"><span class="tag">SSO</span><h2>Войти через компанию</h2><input id="corpSsoEmail" class="input" type="email" inputmode="email" autocomplete="email" placeholder="Рабочий email"><button class="btn" onclick="enterpriseSsoStart()">Продолжить через SSO</button><p class="muted small">Если компания настроила OIDC, вход продолжится через корпоративный Identity Provider.</p></div><div class="card"><span class="tag">ВХОД</span><h2>Корпоративный аккаунт</h2><input id="corpLoginEmail" class="input" type="email" autocomplete="email" placeholder="Email"><input id="corpLoginPassword" class="input" type="password" autocomplete="current-password" placeholder="Пароль"><button class="btn secondary" onclick="enterpriseLogin()">Войти по паролю</button><p class="muted small">Прогресс после входа синхронизируется между устройствами.</p></div><div class="card"><span class="tag">НОВАЯ ОРГАНИЗАЦИЯ</span><h2>Создать корпоративный аккаунт</h2><input id="corpOrg" class="input" placeholder="Компания"><input id="corpName" class="input" autocomplete="name" placeholder="Ваше имя"><input id="corpEmail" class="input" type="email" autocomplete="email" placeholder="Рабочий email"><input id="corpPassword" class="input" type="password" minlength="10" autocomplete="new-password" placeholder="Пароль · минимум 10 символов"><button class="btn" onclick="enterpriseRegister()">Создать организацию</button></div><div class="card"><span class="tag">ПРИГЛАШЕНИЕ</span><h2>Присоединиться к компании</h2><input id="corpJoinCode" class="input" placeholder="Код приглашения"><input id="corpJoinName" class="input" autocomplete="name" placeholder="Ваше имя"><input id="corpJoinEmail" class="input" type="email" autocomplete="email" placeholder="Рабочий email"><input id="corpJoinPassword" class="input" type="password" minlength="10" autocomplete="new-password" placeholder="Пароль · минимум 10 символов"><button class="btn secondary" onclick="enterpriseJoin()">Присоединиться</button></div></div>`
 const u=enterpriseSession.user,team=enterpriseSession.team||[];
 const inviteButtons=enterpriseCan('invite:learner')?`<button class="btn secondary" onclick="enterpriseInvite('learner')">Пригласить сотрудника</button>${enterpriseCan('invite:manager')?`<button class="btn secondary" onclick="enterpriseInvite('manager')">Пригласить менеджера</button>`:''}`:'';
 const teamHtml=enterpriseCan('team:view')?`<h2 class="section-title">Команда</h2><div class="card"><div class="enterprise-team">${team.length?team.map(m=>`<div class="row between enterprise-member"><div><strong>${safe(m.name)}</strong><small class="muted">${safe(m.email)} · ${enterpriseRoleLabel(m.role)}</small></div><div class="row"><div class="small">${m.final!=null?'Итог '+m.final+'%':m.baseline!=null?'Baseline '+m.baseline+'%':'Диагностика —'} · Coach ${m.coachTerms||0}</div>${enterpriseCan('team:roles')&&m.id!==u.id?`<select class="input" aria-label="Роль" onchange="enterpriseChangeRole('${safe(m.id)}',this.value)"><option value="learner" ${m.role==='learner'?'selected':''}>Сотрудник</option><option value="manager" ${m.role==='manager'?'selected':''}>Менеджер</option></select>`:''}${enterpriseCan('team:sessions')&&m.id!==u.id?`<button class="btn secondary" onclick="enterpriseRevokeSessions('${safe(m.id)}')">Завершить сессии</button>`:''}</div></div>`).join(''):'Сотрудников пока нет. Создайте код приглашения.'}</div></div>`:'';
 return `<div class="card"><div class="row between"><div><span class="tag">CORPORATE CLOUD</span><h2>${safe(u.orgName)}</h2><p class="muted">${safe(u.name)} · ${enterpriseRoleLabel(u.role)}</p></div><button class="btn secondary" onclick="enterpriseLogout()">Выйти</button></div><div class="row enterprise-actions"><button class="btn" onclick="enterprisePushState()">Сохранить прогресс</button><button class="btn secondary" onclick="enterprisePullState(true)">Получить с сервера</button>${inviteButtons}</div><p class="muted small">${enterpriseSession.lastSync?'Последняя синхронизация: '+new Date(enterpriseSession.lastSync).toLocaleString('ru-RU'):'Серверная сессия активна.'}</p></div>${enterpriseAssignmentsHtml()}${enterpriseReportsHtml()}${teamHtml}${enterpriseSsoHtml()}${enterpriseScimHtml()}${enterpriseAuditHtml()}`}
const renderOrgV84=renderOrg;
renderOrg=function(){renderOrgV84();const root=$('#view-org');if(!root||enterpriseAssessment)return;root.insertAdjacentHTML('afterbegin',enterpriseAccountHtml())}
setInterval(()=>{if(enterpriseSession.token&&document.visibilityState==='visible')enterprisePushState(true)},60000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&enterpriseSession.token)enterprisePushState(true)});
if(new URL(location.href).searchParams.has('sso_code'))enterpriseSsoExchange();else enterpriseRestore();
